package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.Bundle;import android.text.Spanned;import android.text.style.ForegroundColorSpan;import com.google.android.gms.tasks.Tasks;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class TranslationReadingTest extends Instrumentation {
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
 void await(java.util.function.BooleanSupplier predicate,String message)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+45000;while(android.os.SystemClock.elapsedRealtime()<end){AtomicBoolean ready=new AtomicBoolean();ui(()->ready.set(predicate.getAsBoolean()));if(ready.get())return;Thread.sleep(40);}throw new AssertionError(message);}
 void book(MainActivity a,String text){a.stop();a.text=text;a.chapters=MainActivity.parse(text);a.position=0;a.chapter=0;a.showPosition(true);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();SharedPreferences preferences=getTargetContext().getSharedPreferences("reading_settings",0);Map<String,?> saved=new HashMap<>(preferences.getAll());MainActivity activity=null;boolean passed=false;try{activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","translation_qa").putExtra("book_name","中英译读验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.system.initialized&&a.offlineReady,"voices not ready");check(Tasks.await(a.translation.available(),20,TimeUnit.SECONDS),"translation pack not installed");
 OfflineTranslation.Session direct=a.translation.session(Arrays.asList("小马正在看书。今天阳光明媚。"),"en");String english=direct.get(0);check(english.codePoints().anyMatch(c->c>='A'&&c<='z'),"not translated to English");OfflineTranslation.Session cached=a.translation.session(Arrays.asList("小马正在看书。今天阳光明媚。"),"en");check(english.equals(cached.get(0)),"cache mismatch");cached.cancel();try{cached.get(0);throw new AssertionError("cancelled translation still returned");}catch(CancellationException expected){}
 ui(()->{check(a.voiceButton.getText().toString().startsWith("阅读语言"),"first button name wrong");book(a,"小马正在看书。今天阳光明媚。我们一起去公园散步。这里的花朵开得非常漂亮。");a.applyReadingLanguage("en",false);check(a.ensureReadingVoice(),"English offline voice missing");SystemSpeaker.Option voice=a.system.find(a.systemVoiceKey);check("en".equals(voice.voice.getLocale().getLanguage())&&!voice.voice.isNetworkConnectionRequired(),"wrong English speech voice");a.startReading();});await(()->a.latestStatus.startsWith("离线译读"),"English playback did not start");ui(()->{check(a.latestHighlightStart>=0&&a.latestHighlightEnd>a.latestHighlightStart,"missing logical source highlight");if(a.canDrawReader()){check(a.content.getText() instanceof Spanned,"missing source highlight");Spanned text=(Spanned)a.content.getText();check(text.getSpans(0,text.length(),ForegroundColorSpan.class).length>0,"no highlighted source range");}else result.putBoolean("sourceHighlightDeferredInBackground",true);a.stop();});Thread.sleep(300);ui(()->check(!a.playing&&a.translatedSession==null,"cancelled reading resumed"));result.putBoolean("englishPlaybackAndPause",true);
 ui(()->{book(a,"The little horse is reading a book. The sun is shining today. We are walking in the park and looking at the beautiful flowers.");a.applyReadingLanguage("zh",false);a.systemVoiceKey="";a.offlineVoice=1000;a.startReading();});await(()->a.latestStatus.startsWith("离线译读"),"Chinese playback did not start");ui(()->{check(a.text.startsWith("The little horse"),"source text replaced");if(a.canDrawReader())check(a.content.getText().toString().startsWith("The little horse"),"visible source text replaced");a.stop();a.applyReadingLanguage("",false);check(a.readingLanguage.isEmpty(),"original mode failed");});result.putBoolean("chinesePlayback",true);result.putString("translation",english);result.putString("result","PASS: offline translation both directions; translated system English and local Chinese playback; original highlight; stop cancellation; cache; original mode; first button name");passed=true;
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}SharedPreferences.Editor restore=preferences.edit().clear();for(Map.Entry<String,?> entry:saved.entrySet()){Object value=entry.getValue();if(value instanceof String)restore.putString(entry.getKey(),(String)value);else if(value instanceof Integer)restore.putInt(entry.getKey(),(Integer)value);else if(value instanceof Boolean)restore.putBoolean(entry.getKey(),(Boolean)value);else if(value instanceof Float)restore.putFloat(entry.getKey(),(Float)value);else if(value instanceof Long)restore.putLong(entry.getKey(),(Long)value);}restore.commit();getTargetContext().getSharedPreferences("reader_translation_qa",0).edit().clear().commit();}finish(passed?-1:0,result);}
}
